package com.boopathi.bg.data.local.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Persistent, privacy‑preserving record of a CrossAppWorkflow execution.
 * Only non‑sensitive metadata is stored. No raw UI trees, screenshots, or
 * message bodies are persisted.
 */
@Entity(tableName = "workflow_history")
data class WorkflowHistoryEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0L,
    /** Stable identifier for the workflow (e.g. UUID generated by planner) */
    val workflowId: String,
    /** Short, sanitized description of the user's goal */
    val goalSummary: String,
    /** Lifecycle status – matches CrossAppWorkflowStatus values */
    val status: String,
    /** Index of the last *verified* completed step (0‑based). */
    val stepIndex: Int,
    /** Total number of steps in the workflow */
    val totalSteps: Int,
    /** When the record was created */
    val createdAt: Long = System.currentTimeMillis(),
    /** When the record was last updated */
    val updatedAt: Long = System.currentTimeMillis(),
    /** Optional expiry timestamp after which the record is no longer resumable */
    val expiresAt: Long? = null,
    /** Flag indicating whether the workflow can be safely resumed */
    val resumable: Boolean = false,
    /** Optional sanitized failure reason */
    val failureReason: String? = null
)

